import React from "react";

export default function About() {
  return (
    <div className="about-page">

      {/* HERO */}
      <div className="about-hero">
        <h1>
          I’m a developer who turns <span>ideas into systems</span>.
        </h1>
      </div>

      {/* WRAPPER */}
      <div className="about-wrapper">

        {/* LEFT TIMELINE */}
        <div className="about-left">

          <div className="timeline">

            <div className="item">
              <div className="dot"></div>
              <div className="content">
                <h2>Thinking Style</h2>
                <p>
                  I approach problems by simplifying them into structured components.
                  I first understand the system before writing code. I focus on clarity
                  before complexity, ensuring strong logical foundations.
                </p>
              </div>
            </div>

            <div className="item">
              <div className="dot"></div>
              <div className="content">
                <h2>How I Work</h2>
                <p>
                  Build → Test → Improve → Repeat. I believe strong systems are built
                  through iteration and continuous refinement, improving step by step.
                </p>
              </div>
            </div>

            <div className="item">
              <div className="dot"></div>
              <div className="content">
                <h2>What I Focus On</h2>
                <p>
                  Full-stack development, UI clarity, backend logic, and building real-world
                  applications that solve meaningful problems with efficiency.
                </p>
              </div>
            </div>

          </div>

        </div>

        {/* RIGHT SIDE */}
        <div className="about-right">

          <div className="card main-card">
            <h2>👤 About Me</h2>

            <p>
              I am an Information Technology student passionate about building
              practical and scalable software solutions.
            </p>

            <p>
              I enjoy understanding systems deeply and converting ideas into clean,
              structured applications.
            </p>
          </div>

          <div className="card">
            <h3>🎓 Education</h3>

            <p><strong>B.Tech – Information Technology</strong></p>
            <p className="muted">Panimalar Engineering College</p>

            <div className="row">
              <span>2023 – 2027</span>
              <span className="cgpa">CGPA: 8.81</span>
            </div>
          </div>

          <div className="card">
            <h3>📌 Interests</h3>
            <p>Full Stack Development • Java • UI/UX • DBMS • AI Basics</p>
          </div>

        </div>

      </div>

      {/* STYLE */}
      <style>{`

        .about-page {
          min-height: 100vh;
          padding: 60px 10%;
          font-family: "Poppins", sans-serif;
          background: radial-gradient(circle at top, #0b1220, #050816);
          color: white;
        }

        /* HERO */
        .about-hero h1 {
          font-size: 44px;
          line-height: 1.3;
        }

        .about-hero span {
          color: #38BDF8;
        }

        /* WRAPPER */
        .about-wrapper {
          display: grid;
          grid-template-columns: 1.3fr 1fr;
          gap: 50px;
          margin-top: 40px;
          align-items: stretch;
        }

        /* TIMELINE SYSTEM (KEY FIX) */
        .timeline {
          position: relative;
          padding-left: 25px;
        }

        .timeline::before {
          content: "";
          position: absolute;
          left: 6px;
          top: 5px;
          bottom: 5px;
          width: 2px;
          background: rgba(56,189,248,0.25);
        }

        .item {
          display: flex;
          gap: 15px;
          margin-bottom: 28px; /* reduced gap = tighter + balanced */
        }

        .dot {
          width: 10px;
          height: 10px;
          margin-top: 8px;
          border-radius: 50%;
          background: #38BDF8;
          box-shadow: 0 0 10px #38BDF8;
          z-index: 2;
        }

        .content h2 {
          color: #38BDF8;
          margin-bottom: 6px;
          font-size: 20px;
        }

        .content p {
          color: #cbd5e1;
          line-height: 1.7;
        }

        /* RIGHT SIDE */
        .about-right {
          display: flex;
          flex-direction: column;
          gap: 16px;
        }

        .card {
          padding: 18px;
          border-radius: 14px;
          background: rgba(255,255,255,0.04);
          border: 1px solid rgba(56,189,248,0.15);
        }

        .main-card {
          border: 1px solid rgba(56,189,248,0.3);
          box-shadow: 0 0 18px rgba(56,189,248,0.08);
        }

        h2, h3 {
          color: #38BDF8;
          margin-bottom: 10px;
        }

        p {
          color: #cbd5e1;
          line-height: 1.6;
        }

        .muted {
          color: #94a3b8;
        }

        .row {
          display: flex;
          justify-content: space-between;
          margin-top: 10px;
        }

        .cgpa {
          color: #38BDF8;
          font-weight: 600;
        }

        /* RESPONSIVE */
        @media (max-width: 900px) {
          .about-wrapper {
            grid-template-columns: 1fr;
            gap: 30px;
          }

          .about-hero h1 {
            font-size: 32px;
          }
        }

      `}</style>

    </div>
  );
}
